"""A standalone catalogue for an imaginary moonlit cabinet of curiosities.

This module models fictional archival objects and offers small query and
reporting helpers for that collection. It is unrelated to the portfolio
site and is not part of its build process.
"""

from __future__ import annotations

from dataclasses import dataclass
from datetime import date
from enum import Enum
from typing import Iterable


class ArtifactKind(str, Enum):
    BOOK = "book"
    BOTTLE = "bottle"
    COMPASS = "compass"
    KEY = "key"
    LANTERN = "lantern"
    MAP = "map"
    MIRROR = "mirror"
    ORRERY = "orrery"
    TOKEN = "token"
    WHISTLE = "whistle"


class Condition(str, Enum):
    PRISTINE = "pristine"
    GOOD = "good"
    WORN = "worn"
    FRAGILE = "fragile"


@dataclass(frozen=True, slots=True)
class Artifact:
    """A documented object in the imaginary collection."""

    identifier: str
    name: str
    kind: ArtifactKind
    description: str
    shelf: str
    acquired_on: date
    condition: Condition
    weight_grams: int
    tags: tuple[str, ...]

    def __post_init__(self) -> None:
        if not self.identifier.strip():
            raise ValueError("An artifact needs a non-empty identifier.")
        if not self.name.strip() or not self.description.strip():
            raise ValueError("Artifacts need a name and description.")
        if self.weight_grams < 0:
            raise ValueError("Artifact weight cannot be negative.")
        if not self.shelf.strip():
            raise ValueError("An artifact must be assigned to a shelf.")

    def matches(self, phrase: str) -> bool:
        """Search the name, description, and tags without case sensitivity."""
        needle = phrase.casefold().strip()
        if not needle:
            return True
        searchable = " ".join((self.name, self.description, *self.tags))
        return needle in searchable.casefold()

    def short_label(self) -> str:
        """Format a compact label for a paper shelf card."""
        return f"{self.identifier} · {self.name} [{self.condition.value}]"


@dataclass(frozen=True, slots=True)
class Cabinet:
    """An immutable collection with predictable query helpers."""

    artifacts: tuple[Artifact, ...]

    def __post_init__(self) -> None:
        identifiers = [item.identifier for item in self.artifacts]
        if len(identifiers) != len(set(identifiers)):
            raise ValueError("Artifact identifiers must be unique.")

    def find(self, identifier: str) -> Artifact | None:
        """Look up one item by its stable identifier."""
        return next(
            (item for item in self.artifacts if item.identifier == identifier),
            None,
        )

    def search(self, phrase: str) -> tuple[Artifact, ...]:
        """Return every object that contains a phrase in searchable fields."""
        return tuple(item for item in self.artifacts if item.matches(phrase))

    def by_kind(self, kind: ArtifactKind) -> tuple[Artifact, ...]:
        """Return all artifacts belonging to a particular kind."""
        return tuple(item for item in self.artifacts if item.kind is kind)

    def on_shelf(self, shelf: str) -> tuple[Artifact, ...]:
        """Return shelf contents in catalogue order."""
        return tuple(
            item for item in self.artifacts
            if item.shelf.casefold() == shelf.casefold()
        )

    def total_weight(self) -> int:
        """Add the recorded weights of every object in the cabinet."""
        return sum(item.weight_grams for item in self.artifacts)

    def count_by_kind(self) -> dict[ArtifactKind, int]:
        """Count objects for each kind, including kinds with no objects."""
        counts = {kind: 0 for kind in ArtifactKind}
        for item in self.artifacts:
            counts[item.kind] += 1
        return counts

    def inventory_card(self) -> str:
        """Create a plain-text summary for a fictional curator."""
        counts = self.count_by_kind()
        populated = [
            f"{kind.value}: {count}"
            for kind, count in counts.items()
            if count
        ]
        breakdown = ", ".join(populated) or "no recorded objects"
        return (
            f"Moonlit Cabinet — {len(self.artifacts)} objects\n"
            f"Kinds: {breakdown}\n"
            f"Recorded weight: {self.total_weight()} g"
        )


def first_matching(items: Iterable[Artifact], phrase: str) -> Artifact | None:
    """Find the first matching artifact in any iterable."""
    return next((item for item in items if item.matches(phrase)), None)


